// Mock data for Semesta Souvenir website
// This data will be replaced with backend API calls

export const translations = {
  id: {
    nav: {
      home: 'Beranda',
      about: 'Tentang Kami',
      products: 'Produk',
      contact: 'Kontak'
    },
    hero: {
      title: 'Semesta Souvenir',
      subtitle: 'Elegant & Premium',
      description: 'Mitra terpercaya Anda untuk souvenir berkualitas tinggi dan merchandise custom yang meninggalkan kesan tak terlupakan.',
      cta: 'Lihat Produk',
      ctaSecondary: 'Hubungi Kami'
    },
    features: {
      title: 'Mengapa Memilih Kami',
      items: [
        {
          title: 'Kualitas Premium',
          description: 'Kami menggunakan material terbaik untuk memastikan produk yang tahan lama dan elegan.'
        },
        {
          title: 'Desain Custom',
          description: 'Setiap produk dapat disesuaikan dengan brand dan kebutuhan Anda.'
        },
        {
          title: 'Harga Kompetitif',
          description: 'Dapatkan kualitas terbaik dengan harga yang bersaing di pasar.'
        },
        {
          title: 'Pengiriman Tepat Waktu',
          description: 'Kami berkomitmen mengirimkan pesanan Anda sesuai jadwal yang disepakati.'
        }
      ]
    },
    about: {
      title: 'Tentang Semesta Souvenir',
      subtitle: 'Mitra Souvenir Premium Anda',
      description: 'Semesta Souvenir adalah perusahaan manufaktur souvenir yang berlokasi di Kudus, Jawa Tengah. Kami telah berpengalaman dalam memproduksi berbagai jenis souvenir berkualitas tinggi untuk berbagai kebutuhan, mulai dari acara perusahaan, seminar, hingga perayaan pribadi.',
      vision: {
        title: 'Visi',
        content: 'Menjadi penyedia souvenir premium terdepan yang menghadirkan produk berkualitas tinggi dengan sentuhan elegan untuk setiap momen berharga.'
      },
      mission: {
        title: 'Misi',
        content: 'Menyediakan produk souvenir berkualitas premium dengan desain inovatif, pelayanan terbaik, dan harga kompetitif untuk memenuhi kebutuhan pelanggan.'
      },
      values: [
        { title: 'Kualitas', description: 'Komitmen pada standar tertinggi' },
        { title: 'Inovasi', description: 'Terus berinovasi dalam desain' },
        { title: 'Integritas', description: 'Jujur dan transparan' },
        { title: 'Kepuasan Pelanggan', description: 'Prioritas utama kami' }
      ]
    },
    products: {
      title: 'Produk Kami',
      subtitle: 'Koleksi Souvenir Premium',
      viewAll: 'Lihat Semua',
      orderNow: 'Pesan Sekarang'
    },
    contact: {
      title: 'Hubungi Kami',
      subtitle: 'Siap Membantu Anda',
      description: 'Jangan ragu untuk menghubungi kami untuk konsultasi atau pemesanan. Tim kami siap membantu Anda.',
      form: {
        name: 'Nama Lengkap',
        email: 'Email',
        phone: 'Nomor Telepon',
        product: 'Pilih Produk',
        quantity: 'Jumlah',
        message: 'Pesan / Detail Pesanan',
        submit: 'Kirim Pesanan',
        success: 'Pesanan berhasil dikirim! Kami akan menghubungi Anda segera.'
      },
      info: {
        address: 'Alamat',
        phone: 'Telepon',
        email: 'Email',
        social: 'Media Sosial'
      }
    },
    footer: {
      description: 'Mitra terpercaya Anda untuk souvenir berkualitas tinggi dan merchandise custom.',
      quickLinks: 'Tautan Cepat',
      contactInfo: 'Info Kontak',
      followUs: 'Ikuti Kami',
      copyright: '© 2026 Semesta Souvenir. Hak Cipta Dilindungi.'
    }
  },
  en: {
    nav: {
      home: 'Home',
      about: 'About Us',
      products: 'Products',
      contact: 'Contact'
    },
    hero: {
      title: 'Semesta Souvenir',
      subtitle: 'Elegant & Premium',
      description: 'Your trusted partner for high-quality souvenirs and custom merchandise that leave a lasting impression.',
      cta: 'View Products',
      ctaSecondary: 'Contact Us'
    },
    features: {
      title: 'Why Choose Us',
      items: [
        {
          title: 'Premium Quality',
          description: 'We use the best materials to ensure durable and elegant products.'
        },
        {
          title: 'Custom Design',
          description: 'Every product can be customized to match your brand and needs.'
        },
        {
          title: 'Competitive Pricing',
          description: 'Get the best quality at competitive market prices.'
        },
        {
          title: 'On-Time Delivery',
          description: 'We are committed to delivering your orders on the agreed schedule.'
        }
      ]
    },
    about: {
      title: 'About Semesta Souvenir',
      subtitle: 'Your Premium Souvenir Partner',
      description: 'Semesta Souvenir is a souvenir manufacturing company located in Kudus, Central Java. We have experience in producing various types of high-quality souvenirs for various needs, from corporate events, seminars, to personal celebrations.',
      vision: {
        title: 'Vision',
        content: 'To become the leading premium souvenir provider that delivers high-quality products with an elegant touch for every precious moment.'
      },
      mission: {
        title: 'Mission',
        content: 'To provide premium quality souvenir products with innovative designs, excellent service, and competitive prices to meet customer needs.'
      },
      values: [
        { title: 'Quality', description: 'Commitment to the highest standards' },
        { title: 'Innovation', description: 'Continuously innovating in design' },
        { title: 'Integrity', description: 'Honest and transparent' },
        { title: 'Customer Satisfaction', description: 'Our top priority' }
      ]
    },
    products: {
      title: 'Our Products',
      subtitle: 'Premium Souvenir Collection',
      viewAll: 'View All',
      orderNow: 'Order Now'
    },
    contact: {
      title: 'Contact Us',
      subtitle: 'Ready to Help You',
      description: 'Feel free to contact us for consultation or orders. Our team is ready to assist you.',
      form: {
        name: 'Full Name',
        email: 'Email',
        phone: 'Phone Number',
        product: 'Select Product',
        quantity: 'Quantity',
        message: 'Message / Order Details',
        submit: 'Submit Order',
        success: 'Order submitted successfully! We will contact you soon.'
      },
      info: {
        address: 'Address',
        phone: 'Phone',
        email: 'Email',
        social: 'Social Media'
      }
    },
    footer: {
      description: 'Your trusted partner for high-quality souvenirs and custom merchandise.',
      quickLinks: 'Quick Links',
      contactInfo: 'Contact Info',
      followUs: 'Follow Us',
      copyright: '© 2025 Semesta Souvenir. All Rights Reserved.'
    }
  }
};

export const products = [
  {
    id: 1,
    name: { id: 'Tas Custom', en: 'Custom Bags' },
    description: {
      id: 'Tas berkualitas tinggi dengan desain custom sesuai kebutuhan Anda. Cocok untuk seminar, event perusahaan, dan berbagai acara.',
      en: 'High-quality bags with custom designs according to your needs. Perfect for seminars, corporate events, and various occasions.'
    },
    image: '/img/tas imlek.jpg',
    category: 'bags'
  },
  {
    id: 2,
    name: { id: 'Sticker', en: 'Stickers' },
    description: {
      id: 'Sticker berkualitas dengan berbagai ukuran dan bahan. Dapat dicetak dengan desain apapun sesuai keinginan.',
      en: 'Quality stickers in various sizes and materials. Can be printed with any design as you wish.'
    },
    image: '/img/stk.jpg',
    category: 'stickers'
  },
  {
    id: 3,
    name: { id: 'Topi Ulang Tahun', en: 'Birthday Hats' },
    description: {
      id: 'Topi pesta ulang tahun dengan berbagai desain menarik. Tambahkan kesan meriah pada perayaan Anda.',
      en: 'Birthday party hats with various attractive designs. Add a festive touch to your celebrations.'
    },
    image: '/img/topi.jpg',
    category: 'party'
  },
  {
    id: 4,
    name: { id: 'Backdrop / Banner', en: 'Backdrop / Banner' },
    description: {
      id: 'Backdrop dan banner berkualitas untuk berbagai acara. Cetak dengan resolusi tinggi dan bahan premium.',
      en: 'Quality backdrops and banners for various events. Printed with high resolution and premium materials.'
    },
    image: '/img/bd.jpeg',
    category: 'banners'
  }
];

export const contactInfo = {
  address: 'Kudus, Jawa Tengah, Indonesia',
  phone: '+62 85869015609',
  email: 'semestasouvenir@gmail.com',
  instagram: 'semestasouvenirofficial',
  whatsapp: '+6281234567890'
};
